import{_ as o,o as a,c as e,at as l}from"./chunks/framework.CY22Hent.js";const r="/assets/ai_202603131004.D64xB1rG.png",u="/assets/ai_202603131020.CJbp-PpI.png",L=JSON.parse('{"title":"大语言模型(LLM)笔记","description":"","frontmatter":{"title":"大语言模型(LLM)笔记","date":"2026-03-13T00:00:00.000Z","lastUpdated":"2026-03-13T00:00:00.000Z","categories":["AI"],"tags":["大模型"]},"headers":[],"relativePath":"blogs/AI/大语言模型(LLM)笔记.md","filePath":"blogs/AI/大语言模型(LLM)笔记.md"}'),i={name:"blogs/AI/大语言模型(LLM)笔记.md"};function s(n,t,p,q,_,c){return a(),e("div",null,[...t[0]||(t[0]=[l('<p>[toc]</p><h1 id="大语言模型-llm-笔记" tabindex="-1">大语言模型(LLM)笔记 <a class="header-anchor" href="#大语言模型-llm-笔记" aria-label="Permalink to &quot;大语言模型(LLM)笔记&quot;">​</a></h1><h2 id="大语言模型-llm-介绍" tabindex="-1">大语言模型(LLM) 介绍 <a class="header-anchor" href="#大语言模型-llm-介绍" aria-label="Permalink to &quot;大语言模型(LLM) 介绍&quot;">​</a></h2><p>大语言模型(LLM) 是一个经过海量文本数据训练的深度学习模型，它能够理解和生成人类语言。也是构成AI Agent的基础。</p><p>大语言模型通过分析互联网上的海量文本，学习到语言的统计规律和知识，当它收到输入时，会根据学习到的规律，生成最合理的续写。</p><p>如图所示，大语言模型(LLM) 的工作过程。 <img src="'+r+'" alt="ai_202603131004.png" loading="lazy"></p><blockquote><p>大语言模型的&quot;大&quot;体现在以下几个方面：</p></blockquote><ul><li>参数规模大： 模型内部有数百亿甚至上万亿个可调节的旋钮（即参数）。这些参数记录了学到的语言知识。</li><li>训练数据大：用于训练的文本数据量巨大，是整个互联网公开信息的精华。通过分析海量文本数据，学习到语言的统计规律和知识。</li></ul><blockquote><p>大语言模型的局限性</p></blockquote><ul><li>大语言模型本身无法获取实时数据，只能根据训练时的知识生成文本。</li><li>大语言模型在训练过程中可能会受到训练数据中的偏见影响，导致模型生成的文本中存在偏见。</li><li>大语言模型是一个黑盒子模型，很难解释模型是如何生成文本的。这使得模型的透明度和可解释性较差。</li></ul><h2 id="大语言模型-llm-底层-transformer-架构" tabindex="-1">大语言模型(LLM) 底层： Transformer 架构 <a class="header-anchor" href="#大语言模型-llm-底层-transformer-架构" aria-label="Permalink to &quot;大语言模型(LLM) 底层： Transformer 架构&quot;">​</a></h2><p>LLM 的惊人能力，离不开其底层核心技术——Transformer 架构。</p><p>Transformer 架构是一种基于自注意力机制的神经网络架构，它能够处理序列数据（如文本），并在序列中进行并行计算。</p><blockquote><p>Transformer的核心思想</p></blockquote><p>Transformer的核心思想是利用自注意力机制，将输入文本中的每个元素与其他元素进行注意力计算，从而捕捉到文本中不同元素之间的关系。</p><p>举个例子：假设你要求大语言模型写一篇关于太阳系的文章。</p><ul><li>输入处理：大语言模型会将输入文本（如&quot;写一篇关于太阳系的文章&quot;）先拆分为token（如&quot;写&quot;、&quot;一篇&quot;、&quot;关于&quot;、&quot;太阳系&quot;、&quot;的&quot;、&quot;文章&quot;），然后将每个token转换为模型可以理解的向量表示。</li><li>理解上下文：由于大语言模型内部已经提前学习了海量文本数据，它在学习的过程中，会根据上下文的信息，已经理解了每个token的含义。例如，它知道&quot;关于&quot;通常是描述或介绍的关键词，而&quot;太阳系&quot;则是一个描述的关键词，&quot;文章&quot;则是一个生成文本的token关键词。并且它还会根据当前token，找出其他与之相关的关联词(如太阳，行星什么的)。即进行重复关联。</li><li>组织语言：大语言模型根据重复关联得到的信息，进行组织和生成文本。例如，它可能会根据&quot;关于&quot;和&quot;太阳系&quot;的关联，生成&quot;太阳系是一个由太阳、行星、卫星等组成的天体系统&quot;。</li></ul><blockquote><p>Transformer 的工作方式如图所示</p></blockquote><p><img src="'+u+'" alt="ai_202603131020.png" loading="lazy"></p>',19)])])}const d=o(i,[["render",s]]);export{L as __pageData,d as default};
